-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 9
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 9 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 09', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 09 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-09.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga o que é integração contínua (CI) e o que é entrega contínua (CD).', 0.2, '**Integração contínua (CI)** é juntar o código de todos várias vezes por dia, com a suíte de testes rodando **automaticamente a cada envio**. **Entrega contínua (CD)** é **publicar automaticamente** o que passou pelo CI.', 'Palavras-chave: CI = testes automáticos a cada envio; CD = publicação automática do que passou. Nota cheia (0,2): as duas definições. Metade (0,1): só uma. Zero (0): definições trocadas.'),
      (v_atividade, 1, 2, 'Explique como o CI teria evitado as duas publicações com o carrinho quebrado.', 0.4, 'Com CI, a suíte **roda sozinha a cada push e pull request**; o teste do carrinho teria **falhado no pull request**, o check ficaria **vermelho** e a versão quebrada **não seria juntada nem publicada**. Ninguém precisaria lembrar de rodar os testes.', 'Palavras-chave: roda automaticamente; teste falha no pull request; check vermelho; não publica. Nota cheia (0,4): explicação completa. Metade (0,2): "os testes rodariam" sem dizer que bloqueia a publicação. Zero (0): sem relação com o CI.'),
      (v_atividade, 1, 3, 'Explique por que rodar os testes no servidor, sempre do mesmo jeito, é mais confiável do que depender de alguém rodar à mão.', 0.4, 'O servidor roda os testes **sempre**, **do mesmo jeito** (mesma máquina, mesma versão do Node, mesmas dependências) e **mostra o resultado no pull request** para todos. À mão, a pessoa **esquece**, pula testes ou roda num computador diferente, e o resultado depende de quem rodou.', 'Palavras-chave: sempre; mesmo ambiente; resultado visível para todos; à mão esquece/depende da pessoa. Nota cheia (0,4): as duas comparações. Metade (0,2): só um lado. Zero (0): diz que tanto faz.'),
      (v_atividade, 2, 1, 'Escreva o trecho on que faz o workflow rodar a cada push na main e a cada pull request.', 0.2, 'on: · push: · branches: [main] · pull_request: (com push e pull_request dentro de on, 2 espaços por nível).', 'Palavras-chave: on; push com branches [main]; pull_request. Nota cheia (0,2): trecho completo. Metade (0,1): falta o pull_request ou o filtro da main. Zero (0): sem on.'),
      (v_atividade, 2, 2, 'Escreva o job testes completo: máquina Linux, checkout, setup do Node 20 com cache do npm, instalação e execução da suíte com cobertura.', 0.4, 'jobs: · testes: · runs-on: ubuntu-latest · steps: · - uses: actions/checkout@v4 · - uses: actions/setup-node@v4 com with: node-version: 20 e cache: npm · - run: npm ci · - run: npm run test:coverage', 'Palavras-chave: runs-on ubuntu-latest; actions/checkout; actions/setup-node com node-version 20 e cache npm; npm ci; npm run test:coverage, nessa ordem. Nota cheia (0,4): job completo e na ordem. Metade (0,2): falta um passo ou ordem errada (ex.: npm ci antes do checkout). Zero (0): sem steps.'),
      (v_atividade, 2, 3, 'Explique a diferença entre npm install e npm ci no pipeline e por que os limites de cobertura da aula 7 fazem o job falhar.', 0.4, 'O **npm ci** instala **exatamente o que está no package-lock.json** (e começa do zero), então todas as execuções usam as mesmas versões; o npm install pode atualizar versões e mudar o lock. Os **limites (thresholds) da aula 7** fazem o **npm run test:coverage terminar com erro** abaixo da meta, e o passo com erro **deixa o job vermelho**.', 'Palavras-chave: npm ci = exatamente o package-lock.json; npm install pode mudar versões; thresholds; comando termina com erro; job falha. Nota cheia (0,4): as duas explicações. Metade (0,2): só uma. Zero (0): explicações erradas.'),
      (v_atividade, 3, 1, 'Diga por que o YAML exige cuidado com a indentação e qual é a regra.', 0.2, 'No YAML, a **indentação define a estrutura** (quem está dentro de quem); a regra é **2 espaços por nível, nunca tab**.', 'Palavras-chave: indentação define a estrutura; 2 espaços; nunca tab. Nota cheia (0,2): motivo + regra. Metade (0,1): só a regra. Zero (0): sem a regra.'),
      (v_atividade, 3, 2, 'Escreva o job e2e com needs, checkout e a action do Cypress que inicia a aplicação e espera o endereço responder.', 0.4, 'e2e: · runs-on: ubuntu-latest · needs: testes · steps: · - uses: actions/checkout@v4 · - uses: cypress-io/github-action@v6 com with: start: npm run dev e wait-on: ''http://localhost:5173''', 'Palavras-chave: job e2e; needs: testes; checkout; cypress-io/github-action; start npm run dev; wait-on http://localhost:5173. Nota cheia (0,4): job completo. Metade (0,2): falta o needs ou o start/wait-on. Zero (0): sem a action do Cypress.'),
      (v_atividade, 3, 3, 'Explique o que faz o needs: testes e por que é bom o E2E rodar só depois dos testes unitários e de integração passarem.', 0.4, 'O **needs: testes** faz o job e2e **esperar o job testes e só rodar se ele passar**. É bom porque o E2E é o **mais lento**: se um teste unitário ou de integração já falhou, **não vale gastar minutos** no E2E, e a equipe recebe o erro mais rápido e mais preciso.', 'Palavras-chave: só roda se testes passar; E2E é lento; economiza tempo; erro mais rápido. Nota cheia (0,4): o que faz + por que é bom. Metade (0,2): só uma das partes. Zero (0): diz que roda os dois ao mesmo tempo.'),
      (v_atividade, 4, 1, 'Diga onde, no GitHub, se cria a regra de proteção da branch main.', 0.2, 'No repositório, em **Settings → Branches**, numa regra para a branch **main**.', 'Palavras-chave: Settings; Branches; regra para main. Nota cheia (0,2): caminho certo. Metade (0,1): só "nas configurações". Zero (0): lugar errado.'),
      (v_atividade, 4, 2, 'Diga as duas exigências da regra vistas na aula.', 0.4, '1) Exigir o **status testes (e e2e) aprovado** antes do merge. 2) Exigir pelo menos **1 revisão aprovada** no pull request.', 'Palavras-chave: status/check aprovado antes do merge; 1 revisão aprovada. Nota cheia (0,4): as duas. Metade (0,2): só uma. Zero (0): nenhuma.'),
      (v_atividade, 4, 3, 'Explique o que acontece com um pull request com teste quebrado ou com cobertura abaixo de 70% depois da proteção e o que isso garante para a main.', 0.4, 'O pull request fica com o **check vermelho** e **não pode ser juntado** (o botão de merge fica bloqueado) até a correção. Isso garante que a **main só recebe código testado**, com cobertura dentro da meta.', 'Palavras-chave: check vermelho; merge bloqueado; main só com código testado. Nota cheia (0,4): consequência + garantia. Metade (0,2): só uma das partes. Zero (0): diz que o merge continua livre.'),
      (v_atividade, 5, 1, 'Escreva o comando que instala o vitest-axe e diga o que o axe-core confere.', 0.2, 'npm install -D vitest-axe — O axe-core confere automaticamente **regras de acessibilidade (WCAG)**, como campo sem rótulo, imagem sem texto alternativo, botão sem nome e contraste baixo.', 'Palavras-chave: npm install -D vitest-axe; regras de acessibilidade/WCAG. Nota cheia (0,2): comando + o que confere. Metade (0,1): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 5, 2, 'Escreva o teste "formulário de checkout não tem violações de acessibilidade" com montarCheckout e axe.', 0.4, 'import { it, expect } from ''vitest''; import { axe } from ''vitest-axe''; import { montarCheckout } from ''../src/checkout.js''; it(''formulário de checkout não tem violações de acessibilidade'', async () => { montarCheckout(document.body); const resultado = await axe(document.body); expect(resultado.violations).toHaveLength(0); });', 'Palavras-chave: import de axe de vitest-axe; montarCheckout(document.body); await axe(document.body); expect(resultado.violations).toHaveLength(0). Nota cheia (0,4): teste completo. Metade (0,2): sem await, ou sem montar o checkout. Zero (0): sem o axe.'),
      (v_atividade, 5, 3, 'Explique por que a acessibilidade faz parte da usabilidade e por que o axe não dispensa o teste manual.', 0.4, 'A usabilidade é o usuário **conseguir usar** a tela, e isso inclui pessoas que usam **leitor de tela, teclado ou alto contraste**: uma tela inacessível não é usável para elas. O axe encontra **só parte dos problemas**; o resto exige **teste manual**, como navegar só com o teclado e usar o leitor de tela.', 'Palavras-chave: leitor de tela/teclado/alto contraste; acessibilidade é parte da usabilidade; axe encontra parte; teste manual. Nota cheia (0,4): as duas explicações. Metade (0,2): só uma. Zero (0): diz que o axe encontra tudo.'),
      (v_atividade, 6, 1, 'Diga quem é prejudicado por um campo sem rótulo e por um botão só com ícone.', 0.2, 'Quem usa **leitor de tela**: o campo sem rótulo e o botão só com ícone **não têm nome** para ser lido em voz alta, e a pessoa não sabe o que preencher ou o que o botão faz.', 'Palavras-chave: leitor de tela; sem nome/sem texto para ler. Nota cheia (0,2): quem + por quê. Metade (0,1): só quem. Zero (0): resposta sem relação.'),
      (v_atividade, 6, 2, 'Escreva o HTML corrigido do campo de CEP, da imagem do produto e do botão de lixeira.', 0.4, 'CEP: <label for="cep">CEP</label> <input id="cep" name="cep"> (ou aria-label="CEP" no input). Imagem: <img src="fone.jpg" alt="Fone de ouvido sem fio preto">. Botão: <button aria-label="Remover item">🗑️</button>.', 'Palavras-chave: label com for igual ao id (ou aria-label); alt descritivo; aria-label no botão. Nota cheia (0,4): as três correções. Metade (0,2): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 6, 3, 'Explique como corrigir o contraste baixo, citando a relação mínima, e como conferir depois da correção.', 0.4, 'Ajustar as cores do texto e do fundo (por exemplo, escurecer o texto) até a relação de contraste mínima de **4,5:1**. Depois da correção, **rodar o axe de novo** (o teste de acessibilidade volta a ficar verde) e conferir visualmente.', 'Palavras-chave: ajustar cores; 4,5:1; rodar o axe de novo. Nota cheia (0,4): correção com 4,5:1 + conferência. Metade (0,2): só uma das partes. Zero (0): sem a relação e sem conferência.'),
      (v_atividade, 7, 1, 'Diga onde se roda o Lighthouse e em que modo a página deve ser auditada.', 0.2, 'No **Chrome DevTools → Lighthouse**, auditando a página no **modo mobile**.', 'Palavras-chave: DevTools; Lighthouse; mobile. Nota cheia (0,2): lugar + modo. Metade (0,1): só um. Zero (0): nenhum.'),
      (v_atividade, 7, 2, 'Explique o que medem LCP, INP e CLS e diga o valor considerado bom de cada um.', 0.4, '**LCP (Largest Contentful Paint):** tempo até o **maior elemento aparecer** — bom até **2,5 s**. **INP (Interaction to Next Paint):** tempo de **resposta a cliques e toques** — bom até **200 ms**. **CLS (Cumulative Layout Shift):** quanto a página **"pula"** enquanto carrega — bom até **0,1**.', 'Palavras-chave: maior elemento/2,5 s; resposta a cliques/200 ms; página pula/0,1. Nota cheia (0,4): os três com o que medem e o valor bom. Metade (0,2): os três sem os valores, ou dois completos. Zero (0): um ou nenhum.'),
      (v_atividade, 7, 3, 'Explique por que o desempenho é uma questão de qualidade para o cliente da loja.', 0.4, 'Uma página **lenta**, que **pula** ou que **demora a responder** atrapalha o cliente: ele **clica no lugar errado**, **desiste da compra** e vai para outra loja, principalmente no celular. O sistema pode estar "certo" e mesmo assim ter **baixa qualidade** para quem usa.', 'Palavras-chave: cliente desiste/abandona; clica errado; celular; qualidade para quem usa. Nota cheia (0,4): explicação com efeito no cliente. Metade (0,2): "fica mais rápido" sem efeito no cliente. Zero (0): diz que desempenho não importa.'),
      (v_atividade, 8, 1, 'Diga se o LCP de 4,8 s é bom e qual é a primeira melhoria a testar.', 0.2, '**Não é bom** (o bom é até 2,5 s). A primeira melhoria é **otimizar a imagem de 3 MB** (comprimir, reduzir o tamanho, formato moderno como WebP).', 'Palavras-chave: não é bom; acima de 2,5 s; otimizar a imagem. Nota cheia (0,2): diagnóstico + melhoria. Metade (0,1): só um. Zero (0): diz que 4,8 s é bom.'),
      (v_atividade, 8, 2, 'Escreva a tag img da vitrine com as melhorias para o LCP e para o CLS, e explique cada atributo.', 0.4, '<img src="vitrine-800.webp" alt="Fone de ouvido sem fio preto" width="800" height="600"> — o **src** aponta para a **imagem otimizada** (menor, WebP), que carrega mais rápido e melhora o **LCP**; **width e height** reservam o **espaço da imagem** antes de ela chegar, e a página **não pula** (**CLS**); o **alt** mantém a acessibilidade.', 'Palavras-chave: imagem otimizada (LCP); width e height definidos (CLS); alt. Nota cheia (0,4): tag com os atributos + explicação. Metade (0,2): tag sem explicação, ou falta width/height. Zero (0): sem melhoria na tag.'),
      (v_atividade, 8, 3, 'Proponha uma melhoria para o INP e uma para o que fica fora da tela, e explique por que cada uma ajuda.', 0.4, '**INP:** carregar **menos JavaScript na carga inicial** (dividir o código, adiar scripts que não são da primeira tela), para o navegador ficar livre e **responder rápido ao clique**. **Fora da tela:** **carregamento sob demanda** (loading="lazy" nas imagens de baixo), para a página baixar primeiro **só o que o cliente vê** e o resto quando ele rolar.', 'Palavras-chave: menos JavaScript na carga inicial; resposta ao clique; carregamento sob demanda/lazy; baixa só o que se vê. Nota cheia (0,4): as duas melhorias com o porquê. Metade (0,2): só uma, ou as duas sem o porquê. Zero (0): nenhuma correta.'),
      (v_atividade, 9, 1, 'Diga o que o CI informa à equipe no pull request.', 0.2, 'O CI informa **a todos se a alteração passou** nos testes (check **verde** ou **vermelho**) e mostra **qual teste falhou**.', 'Palavras-chave: passou ou não; check verde/vermelho; visível para todos. Nota cheia (0,2): resposta completa. Metade (0,1): "mostra os testes" sem o resultado. Zero (0): sem relação.'),
      (v_atividade, 9, 2, 'Descreva, em ordem, os passos do fluxo: alterar, abrir o pull request, revisar, corrigir e juntar.', 0.4, '1) Criar uma **branch** e fazer a alteração (o teste quebrado). 2) **Abrir o pull request**; todos acompanham o **check ficar vermelho**. 3) Outro integrante **revisa e comenta** onde está a falha. 4) Alguém **corrige numa nova alteração** e o check fica **verde**. 5) Um integrante **aprova** e o **merge é liberado**.', 'Palavras-chave: branch; pull request com check vermelho; revisão com comentário; correção com check verde; aprovação e merge. Nota cheia (0,4): os cinco passos em ordem. Metade (0,2): três ou quatro passos, ou fora de ordem. Zero (0): dois ou menos.'),
      (v_atividade, 9, 3, 'Explique por que é melhor o defeito ser pego no pull request do que depois de chegar à main.', 0.4, 'No pull request, o defeito é pego **antes de afetar alguém**: a correção é **rápida e barata** e só a equipe vê. Na main, o defeito pode ir **para a loja publicada** (como o carrinho quebrado), **atingir clientes**, causar **prejuízo** e atrapalhar o trabalho de todos que usam a main.', 'Palavras-chave: antes de afetar clientes; correção barata; main publicada afeta clientes/prejuízo. Nota cheia (0,4): os dois lados. Metade (0,2): só um lado. Zero (0): diz que tanto faz.'),
      (v_atividade, 10, 1, 'Diga o que mostra o badge no README.md.', 0.2, 'O badge mostra **o estado dos testes da main** (passando ou falhando) **para qualquer pessoa** que abrir o repositório.', 'Palavras-chave: estado da main; passando/falhando; visível para qualquer pessoa. Nota cheia (0,2): resposta completa. Metade (0,1): "mostra os testes" sem o estado. Zero (0): sem relação.'),
      (v_atividade, 10, 2, 'Escreva a linha do badge do workflow ci.yml no README.md.', 0.4, '![Testes](https://github.com/<usuario>/<repositorio>/actions/workflows/ci.yml/badge.svg)', 'Palavras-chave: imagem Markdown ![...](...); github.com/<usuario>/<repositorio>/actions/workflows/ci.yml/badge.svg (usuário e repositório reais também valem). Nota cheia (0,4): linha completa e correta. Metade (0,2): endereço sem /badge.svg ou sem o nome do workflow. Zero (0): sem a imagem do badge.'),
      (v_atividade, 10, 3, 'Diga o que o TESTING.md documenta e explique como ele ajuda a interação com a equipe de testes.', 0.4, 'O TESTING.md documenta **como rodar a suíte**, a **estratégia de testes** e **como contribuir com testes**. Ele ajuda a equipe porque qualquer integrante novo **sabe sozinho** rodar e escrever testes **do mesmo jeito** que os outros, e as conversas no pull request partem de regras **combinadas por escrito**.', 'Palavras-chave: como rodar; estratégia; como contribuir; integrante novo; mesmo jeito/regras combinadas. Nota cheia (0,4): conteúdo + como ajuda. Metade (0,2): só uma das partes. Zero (0): sem relação.');
end $$;
